import{_ as a,o as t,c as o,a4 as n}from"./chunks/framework.CAgiNEKA.js";const u=JSON.parse('{"title":"OpenClaw 接入指南","description":"","frontmatter":{"title":"OpenClaw 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["OpenClaw","AI客户端","接入教程","国产开源"]},"headers":[],"relativePath":"connect/openclaw.md","filePath":"connect/openclaw.md","lastUpdated":1779073000000}'),r={name:"connect/openclaw.md"};function l(p,e,d,i,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="openclaw-接入指南" tabindex="-1">OpenClaw 接入指南 <a class="header-anchor" href="#openclaw-接入指南" aria-label="Permalink to &quot;OpenClaw 接入指南&quot;">​</a></h1><p>国产开源 AI 客户端，接入熊猫Token平台轻松调用各大模型。</p><p><strong>预计用时：5 分钟 · 支持平台：Win / Mac / Linux · 国产自主研发</strong></p><hr><h2 id="什么是-openclaw" tabindex="-1">什么是 OpenClaw？ <a class="header-anchor" href="#什么是-openclaw" aria-label="Permalink to &quot;什么是 OpenClaw？&quot;">​</a></h2><p>OpenClaw 是一款国产开源的跨平台 AI 聊天客户端，界面简洁，支持自定义 API 接入，可配合各类 API 聚合平台使用，无需折腾复杂配置即可使用 GPT、Claude、DeepSeek 等模型。</p><hr><h2 id="step-01-下载安装-openclaw" tabindex="-1">Step 01：下载安装 OpenClaw <a class="header-anchor" href="#step-01-下载安装-openclaw" aria-label="Permalink to &quot;Step 01：下载安装 OpenClaw&quot;">​</a></h2><h3 id="_1-前往官方-github-下载" tabindex="-1">1. 前往官方 GitHub 下载 <a class="header-anchor" href="#_1-前往官方-github-下载" aria-label="Permalink to &quot;1. 前往官方 GitHub 下载&quot;">​</a></h3><p>访问 OpenClaw 的 GitHub 仓库 Releases 页面，根据你的系统下载对应安装包：</p><ul><li>Windows：选 <code>.exe</code></li><li>macOS：选 <code>.dmg</code></li></ul><h3 id="_2-安装并启动" tabindex="-1">2. 安装并启动 <a class="header-anchor" href="#_2-安装并启动" aria-label="Permalink to &quot;2. 安装并启动&quot;">​</a></h3><p>双击安装包按提示完成安装，启动 OpenClaw。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录并创建令牌" tabindex="-1">1. 登录并创建令牌 <a class="header-anchor" href="#_1-登录并创建令牌" aria-label="Permalink to &quot;1. 登录并创建令牌&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，注册登录后进入「控制台」→「令牌」，新建令牌并复制。</p><hr><h2 id="step-03-在-openclaw-中配置" tabindex="-1">Step 03：在 OpenClaw 中配置 <a class="header-anchor" href="#step-03-在-openclaw-中配置" aria-label="Permalink to &quot;Step 03：在 OpenClaw 中配置&quot;">​</a></h2><h3 id="_1-打开设置" tabindex="-1">1. 打开设置 <a class="header-anchor" href="#_1-打开设置" aria-label="Permalink to &quot;1. 打开设置&quot;">​</a></h3><p>启动 OpenClaw 后，点击左下角或顶部的「设置」入口，进入 API 配置页面。</p><h3 id="_2-选择-openai-兼容模式" tabindex="-1">2. 选择 OpenAI 兼容模式 <a class="header-anchor" href="#_2-选择-openai-兼容模式" aria-label="Permalink to &quot;2. 选择 OpenAI 兼容模式&quot;">​</a></h3><p>在模型服务商选择中，选择「OpenAI 兼容」或「自定义」选项。</p><h3 id="_3-填写配置信息" tabindex="-1">3. 填写配置信息 <a class="header-anchor" href="#_3-填写配置信息" aria-label="Permalink to &quot;3. 填写配置信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>API 地址 / Base URL</td><td><code>https://www.pandatoken.net/v1</code></td></tr><tr><td>API Key</td><td>你从平台复制的令牌</td></tr><tr><td>模型名称</td><td>例如 <code>deepseek-v3</code>、<code>gpt-4o</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">提示</p><p>熊猫Token平台与 OpenAI API 完全兼容，凡是支持自定义 Base URL 的客户端均可按此方式接入。</p></div><h3 id="_4-保存并开始使用" tabindex="-1">4. 保存并开始使用 <a class="header-anchor" href="#_4-保存并开始使用" aria-label="Permalink to &quot;4. 保存并开始使用&quot;">​</a></h3><p>保存配置后，在聊天界面选择对应模型，即可开始对话。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>连接失败 / 无响应</strong></p><p>检查 API 地址是否填写正确，确认末尾带 <code>/v1</code>。同时确认 API Key 完整，没有多余空格或换行符。</p><hr><p>配置完成！OpenClaw 已成功接入熊猫Token平台，国产客户端畅用全球模型。</p>',34)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
